import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim, cents } from './claims.service';
import { Grade } from './people.service';

export interface Rate {
  grade: Grade;
  /** The percent with two decimals, as text (e.g. "12.50"). */
  pct: string;
  /** The date the rate applies from (YYYY-MM-DD); null when it applies from the beginning of time. */
  from: string | null;
}

/** The grade's rate in force on a date: the one with the latest from-date on or before it, or the
 *  one with no from-date when none has; null when no rate applies yet. */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct ?? null;
}

/** What is due on an amount at a rate: amount times pct, divided by 100, rounded half to even to
 *  two decimals; null when there is no rate. Worked in whole cents and hundredths of a percent, so
 *  it is exact. */
export function dueCents(amountCents: number, pct: string | null): number | null {
  if (pct === null) return null;
  const product = BigInt(amountCents) * BigInt(Math.round(Number(pct) * 100));
  const negative = product < 0n;
  const abs = negative ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
  return Number(negative ? -quotient : quotient);
}

/** What is due on a claim, in cents: a claim settled at a rate keeps what was due on it then; a
 *  claim a statement bound keeps the figure it was bound to (null when that was none); otherwise
 *  what is due on its amount at its person's grade's rate in force on the claim's date, raised to
 *  the sheet's floor (in cents) when below it, null when no rate applies then. */
export function claimDueCents(claim: Claim, rates: Rate[], grade: Grade, floorCents: number): number | null {
  if (claim.status === 'SETTLED' && claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
  const due = dueCents(cents(claim.amount), rateOn(rates, grade, claim.date));
  return due === null ? null : Math.max(due, floorCents);
}

// The rates of the grades on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheet), { headers: this.session.headers() }));
  }

  /** A null from sets the rate that applies from the beginning of time. */
  set(sheet: string, grade: Grade, pct: string, from: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheet)}/${grade}`, { pct, from }, { headers: this.session.headers() }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** A user's role on a sheet: every name is a clerk unless made a steward. */
export type Role = 'clerk' | 'steward';

export const ROLES: readonly Role[] = ['clerk', 'steward'];

export interface RoleGiven {
  user: string;
  role: Role;
}

/** The floor a sheet starts with, in cents. */
export const FLOOR_CENTS = 100;

/** The terms a sheet starts with, in days. */
export const TERMS_DAYS = 14;

export interface SheetSettings {
  /** The most a clerk may settle a claim for, with two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due can be, with two decimals. */
  floor: string;
  /** How many days after its date a claim is due by. */
  terms: number;
  /** The roles given on the sheet, by user name. */
  roles: RoleGiven[];
}

// The settings of a sheet (its roles, its clerk limit, its floor and its terms), read from and written to the server.
@Injectable({ providedIn: 'root' })
export class SettingsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  get(sheet: string): Promise<SheetSettings> {
    return firstValueFrom(
      this.http.get<SheetSettings>(`${this.url(sheet)}/settings`, { headers: this.session.headers() }),
    );
  }

  /** A null value removes the limit. */
  setClerkLimit(sheet: string, value: string | null): Promise<SheetSettings> {
    return firstValueFrom(
      this.http.put<SheetSettings>(
        `${this.url(sheet)}/settings/clerk-limit`,
        { value },
        { headers: this.session.headers() },
      ),
    );
  }

  setFloor(sheet: string, value: string): Promise<SheetSettings> {
    return firstValueFrom(
      this.http.put<SheetSettings>(`${this.url(sheet)}/settings/floor`, { value }, { headers: this.session.headers() }),
    );
  }

  setTerms(sheet: string, value: string): Promise<SheetSettings> {
    return firstValueFrom(
      this.http.put<SheetSettings>(`${this.url(sheet)}/settings/terms`, { value }, { headers: this.session.headers() }),
    );
  }

  setRole(sheet: string, user: string, role: Role): Promise<RoleGiven> {
    return firstValueFrom(
      this.http.put<RoleGiven>(
        `${this.url(sheet)}/roles/${encodeURIComponent(user)}`,
        { role },
        { headers: this.session.headers() },
      ),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}`;
  }
}
import { Component, effect, inject, output, signal } from '@angular/core';
import { cents } from './claims.service';
import { Session } from '../../core/session';
import { ROLES, Role, RoleGiven, SettingsService, SheetSettings } from './settings.service';

const LIMIT = /^\d{1,10}(\.\d{1,2})?$/;
const TERMS = /^\d{1,4}$/;

// The sheet's settings: its clerk limit (the most a clerk may settle a claim for; blank for no
// limit), its floor (the least a claim's live due can be), its terms (how many days after its date
// a claim is due by) and the role each user name has been given (any other name is a clerk). Read from the
// store every time a sheet is loaded. Saving the settings saves only the fields changed since
// they were last saved.
@Component({
  selector: 'app-settings',
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <form (submit)="saveSettings($event)" aria-label="Settings" data-testid="settings-form">
        <label for="setting-clerk-limit">Clerk limit</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); limitChanged = true; settingsError.set(null)"
        />
        <span>
          In force: <span data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</span>
          @if (clerkLimit() === null) {
            (no limit)
          }
        </span>
        <label for="setting-floor">Floor</label>
        <input
          id="setting-floor"
          data-testid="setting-floor"
          inputmode="decimal"
          [value]="floorInput()"
          (input)="floorInput.set(value($event)); floorChanged = true; settingsError.set(null)"
        />
        <span>In force: <span data-testid="setting-floor-current">{{ floor() }}</span></span>
        <label for="setting-terms">Terms (days)</label>
        <input
          id="setting-terms"
          data-testid="setting-terms"
          inputmode="numeric"
          [value]="termsInput()"
          (input)="termsInput.set(value($event)); termsChanged = true; settingsError.set(null)"
        />
        <span>In force: <span data-testid="setting-terms-current">{{ terms() }}</span></span>
        <button type="submit" data-testid="settings-save">Save settings</button>
        @if (settingsError(); as message) {
          <p role="alert" class="error" data-testid="settings-error">{{ message }}</p>
        }
      </form>

      <form (submit)="saveRole($event)" aria-label="Role" data-testid="role-form">
        <label for="role-form-user">User</label>
        <input
          id="role-form-user"
          data-testid="role-form-user"
          [value]="roleUser()"
          (input)="roleUser.set(value($event)); roleError.set(null)"
        />
        <label for="role-form-role">Role</label>
        <input
          id="role-form-role"
          data-testid="role-form-role"
          list="role-form-roles"
          [value]="role()"
          (input)="role.set(value($event)); roleError.set(null)"
        />
        <datalist id="role-form-roles">
          @for (r of roles; track r) {
            <option [value]="r"></option>
          }
        </datalist>
        <button type="submit" data-testid="role-form-submit">Set role</button>
        @if (roleError(); as message) {
          <p role="alert" class="error" data-testid="role-form-error">{{ message }}</p>
        }
      </form>
      @if (given().length > 0) {
        <table data-testid="role-list">
          <caption>Roles (anyone else is a clerk)</caption>
          <thead>
            <tr>
              <th scope="col">User</th>
              <th scope="col">Role</th>
            </tr>
          </thead>
          <tbody>
            @for (r of given(); track r.user) {
              <tr [attr.data-testid]="'role-row-' + r.user">
                <td data-testid="role-user">{{ r.user }}</td>
                <td data-testid="role-value">{{ r.role }}</td>
              </tr>
            }
          </tbody>
        </table>
      }
    </section>
  `,
  styles: `
    form {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      margin-bottom: 0.5rem;
    }
    .error {
      color: #a40000;
      margin: 0;
    }
    table {
      border-collapse: collapse;
      margin-bottom: 1rem;
    }
    caption {
      text-align: left;
      font-weight: bold;
    }
    th,
    td {
      text-align: left;
      padding: 0.25rem 0.75rem 0.25rem 0;
    }
  `,
})
export class Settings {
  private readonly session = inject(Session);
  private readonly service = inject(SettingsService);

  protected readonly roles = ROLES;
  /** The clerk limit in force; null when there is none. */
  protected readonly clerkLimit = signal<string | null>(null);
  /** The floor in force, with two decimals; empty until read. */
  protected readonly floor = signal('');
  protected readonly given = signal<RoleGiven[]>([]);
  /** The terms in force, in days, as text; empty until read. */
  protected readonly terms = signal('');
  /** The floor saved, in cents. */
  readonly floorSaved = output<number>();
  /** The terms saved, in days. */
  readonly termsSaved = output<number>();

  protected readonly limit = signal('');
  protected readonly floorInput = signal('');
  protected readonly termsInput = signal('');
  /** Whether each field was typed in since the settings were last loaded or saved; a field is saved
   *  when it was, or when it differs from the value in force. */
  protected limitChanged = false;
  protected floorChanged = false;
  protected termsChanged = false;
  protected readonly settingsError = signal<string | null>(null);
  protected readonly roleUser = signal('');
  protected readonly role = signal('');
  protected readonly roleError = signal<string | null>(null);
  /** A submit is waiting for its answer; another submit of the same form meanwhile is ignored. */
  private savingSettings = false;
  private savingRole = false;

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      this.session.loads();
      this.clerkLimit.set(null);
      this.floor.set('');
      this.given.set([]);
      this.limit.set('');
      this.floorInput.set('');
      this.terms.set('');
      this.termsInput.set('');
      this.limitChanged = false;
      this.floorChanged = false;
      this.termsChanged = false;
      this.settingsError.set(null);
      this.roleUser.set('');
      this.role.set('');
      this.roleError.set(null);
      if (sheet) void this.read(sheet);
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected async saveSettings(event: Event): Promise<void> {
    event.preventDefault();
    if (this.savingSettings) return;
    this.settingsError.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const limit = this.limit().trim();
    const floor = this.floorInput().trim();
    const saveLimit = this.limitChanged || limit !== (this.clerkLimit() ?? '');
    const saveFloor = this.floorChanged || floor !== this.floor();
    const terms = this.termsInput().trim();
    const saveTerms = this.termsChanged || terms !== this.terms();
    if (saveLimit && limit !== '' && !LIMIT.test(limit)) {
      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
      return;
    }
    if (saveFloor && !LIMIT.test(floor)) {
      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
      return;
    }
    if (saveTerms && !TERMS.test(terms)) {
      this.settingsError.set('Type terms as a whole number of days, 0 or more.');
      return;
    }
    this.savingSettings = true;
    try {
      if (saveLimit) {
        const settings = await this.service.setClerkLimit(sheet, limit || null);
        if (this.session.sheetId() !== sheet) return;
        this.limitChanged = false;
        this.show(settings);
      }
      if (saveFloor) {
        const settings = await this.service.setFloor(sheet, floor);
        if (this.session.sheetId() !== sheet) return;
        this.floorChanged = false;
        this.show(settings);
        this.floorSaved.emit(cents(settings.floor));
      }
      if (saveTerms) {
        const settings = await this.service.setTerms(sheet, terms);
        if (this.session.sheetId() !== sheet) return;
        this.termsChanged = false;
        this.show(settings);
        this.termsSaved.emit(settings.terms);
      }
      this.limit.set(this.clerkLimit() ?? '');
      this.floorInput.set(this.floor());
      this.termsInput.set(this.terms());
    } catch {
      this.settingsError.set('Those settings could not be saved.');
    } finally {
      this.savingSettings = false;
    }
  }

  protected async saveRole(event: Event): Promise<void> {
    event.preventDefault();
    if (this.savingRole) return;
    this.roleError.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const user = this.roleUser().trim();
    const role = this.role().trim();
    if (user === '') {
      this.roleError.set('Type a user name.');
      return;
    }
    if (!ROLES.includes(role as Role)) {
      this.roleError.set(`Choose a role: ${ROLES.join(' or ')}.`);
      return;
    }
    this.savingRole = true;
    try {
      const saved = await this.service.setRole(sheet, user, role as Role);
      if (this.session.sheetId() !== sheet) return;
      this.given.update((list) =>
        [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
      );
      this.roleUser.set('');
      this.role.set('');
    } catch {
      this.roleError.set('That role could not be set.');
    } finally {
      this.savingRole = false;
    }
  }

  private async read(sheet: string): Promise<void> {
    try {
      const settings = await this.service.get(sheet);
      if (this.session.sheetId() === sheet) {
        this.show(settings);
        if (!this.limitChanged) this.limit.set(settings.clerkLimit ?? '');
        if (!this.floorChanged) this.floorInput.set(settings.floor);
        if (!this.termsChanged) this.termsInput.set(String(settings.terms));
      }
    } catch {
      // The settings could not be read; they show as none.
    }
  }

  private show(settings: SheetSettings): void {
    this.clerkLimit.set(settings.clerkLimit);
    this.floor.set(settings.floor);
    this.terms.set(String(settings.terms));
    this.given.set(settings.roles);
  }
}

